<?php
/** Render one allowlisted section from the original Service ACF field group. */
$type = (string) get_sub_field( 'section_type' );
$source_mode = (string) get_sub_field( 'content_source' );
$source_id = 'another_service' === $source_mode ? (int) get_sub_field( 'source_service' ) : get_the_ID();
$field_map = array(
	'advertising_core'       => 'advertising_core_warp_section',
	'brands'                 => 'our_valuable_brands',
	'store_development'      => 'store_development',
	'experiences'            => 'experiences_warp_section',
	'advertising_with_image' => 'advertising_core_warp_section_with_image',
	'support_growth'         => 'support_warp_growth_section',
	'performance'            => 'performance_section',
	'service_brand'          => 'service_brand',
	'faq'                    => 'faq_section',
);
if ( ! $source_id || ! isset( $field_map[ $type ] ) ) { return; }
$data = get_field( $field_map[ $type ], $source_id );
if ( ! is_array( $data ) || ! array_filter( $data ) ) {
	if ( current_user_can( 'edit_post', get_the_ID() ) ) {
		printf(
			'<div class="service-v2-editor-notice">%s</div>',
			esc_html( sprintf( __( 'The selected source service has no content in the legacy field: %s.', 'di-infotech' ), $field_map[ $type ] ) )
		);
	}
	return;
}
$uid = 'legacy-' . sanitize_html_class( $type ) . '-' . absint( $source_id ) . '-' . absint( get_row_index() );
$image = static function ( $value, $size = 'large', $class = '' ) {
	if ( is_array( $value ) && ! empty( $value['ID'] ) ) { return wp_get_attachment_image( (int) $value['ID'], $size, false, array( 'class' => $class, 'loading' => 'lazy' ) ); }
	if ( is_numeric( $value ) ) { return wp_get_attachment_image( (int) $value, $size, false, array( 'class' => $class, 'loading' => 'lazy' ) ); }
	if ( is_array( $value ) && ! empty( $value['url'] ) ) { return '<img class="' . esc_attr( $class ) . '" src="' . esc_url( $value['url'] ) . '" alt="' . esc_attr( $value['alt'] ?? '' ) . '" loading="lazy">'; }
	return '';
};
?>
<?php if ( 'advertising_core' === $type ) : ?>
	<section class="advertising-wrp grey-bg padding_top_bottom"><div class="container">
		<?php if ( ! empty( $data['heading'] ) ) : ?><div class="heading text-center"><h2><?php echo esc_html( $data['heading'] ); ?></h2></div><?php endif; ?>
		<?php if ( ! empty( $data['advertising_nav_section'] ) ) : ?><ul class="advertising-nav nav nav-pills mb-3" role="tablist"><?php foreach ( $data['advertising_nav_section'] as $i => $tab ) : ?><li class="nav-item"><button class="nav-link<?php echo 0 === $i ? ' active' : ''; ?>" data-bs-toggle="pill" data-bs-target="#<?php echo esc_attr( $uid . '-' . $i ); ?>" type="button"><?php echo esc_html( $tab['advertising_nav_heading'] ?? '' ); ?></button></li><?php endforeach; ?></ul>
		<div class="tab-content"><?php foreach ( $data['advertising_nav_section'] as $i => $tab ) : ?><div class="tab-pane fade<?php echo 0 === $i ? ' show active' : ''; ?>" id="<?php echo esc_attr( $uid . '-' . $i ); ?>"><div class="row"><?php foreach ( (array) ( $tab['advertising_nav_details_section'] ?? array() ) as $item ) : ?><div class="col-lg-4 col-sm-6"><div class="advertising-content-wrp"><div class="heading"><h3><?php echo esc_html( $item['heading'] ?? '' ); ?></h3><div class="sub_pera grey-text"><?php echo wp_kses_post( wpautop( $item['advertising_nav_details'] ?? '' ) ); ?></div></div></div></div><?php endforeach; ?></div></div><?php endforeach; ?></div><?php endif; ?>
	</div></section>
<?php elseif ( 'brands' === $type ) : ?>
	<section class="brands padding_top_bottom"><div class="container"><div class="row justify-content-center"><div class="col-lg-8"><div class="heading text-center"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><?php echo wp_kses_post( wpautop( $data['discription'] ?? '' ) ); ?></div></div></div><div class="row justify-content-center"><?php foreach ( (array) ( $data['our_brands'] ?? array() ) as $brand ) : ?><div class="col-lg-2 col-sm-3 col-6"><div class="brand_img"><?php echo $image( $brand['brands_logo'] ?? null, 'medium' ); // phpcs:ignore ?></div></div><?php endforeach; ?></div></div></section>
<?php elseif ( 'store_development' === $type ) : ?>
	<section class="work-process-wrp padding_top_bottom"><div class="container"><div class="row justify-content-center"><div class="col-lg-8"><div class="experiences-text text-center"><div class="heading"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><div class="sub_pera grey-text"><?php echo wp_kses_post( wpautop( $data['description'] ?? '' ) ); ?></div></div></div></div></div>
	<?php $tabs = (array) ( $data['work_process_tab_menu'] ?? array() ); if ( $tabs ) : ?><div class="row align-items-center"><div class="col-lg-6"><div class="work-process-tab"><div class="nav flex-column nav-pills" role="tablist"><?php foreach ( $tabs as $i => $tab ) : ?><button class="nav-link<?php echo 0 === $i ? ' active' : ''; ?>" data-bs-toggle="pill" data-bs-target="#<?php echo esc_attr( $uid . '-' . $i ); ?>" type="button"><?php echo esc_html( $tab['work_process_tab_menu_name'] ?? '' ); ?></button><?php endforeach; ?></div></div></div><div class="col-lg-6"><div class="tab-content"><?php foreach ( $tabs as $i => $tab ) : ?><div class="tab-pane fade<?php echo 0 === $i ? ' show active' : ''; ?>" id="<?php echo esc_attr( $uid . '-' . $i ); ?>"><div class="work-process-text"><?php $banners = (array) ( $tab['work_process_tab_bammer'] ?? array() ); if ( $banners ) : ?><div class="ad-slider1 owl-carousel owl-theme"><?php foreach ( $banners as $banner ) : ?><div class="item social-media-img"><?php echo $image( $banner['image'] ?? null ); // phpcs:ignore ?></div><?php endforeach; ?></div><?php endif; ?><div class="main-nav"><p class="bg_yellow"><?php echo esc_html( $tab['work_process_tab_menu_name'] ?? '' ); ?></p></div><div class="sub_pera"><?php echo wp_kses_post( wpautop( $tab['work_process_tab_detials'] ?? '' ) ); ?></div></div></div><?php endforeach; ?></div></div></div><?php endif; ?></div></section>
<?php elseif ( 'experiences' === $type ) : ?>
	<section class="experiences-wrp grey-bg padding_top_bottom"><div class="container"><div class="experiences-text"><div class="heading"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><div class="sub_pera"><?php echo wp_kses_post( $data['description'] ?? '' ); ?></div></div></div><div class="row"><?php foreach ( (array) ( $data['experiences_are'] ?? array() ) as $item ) : ?><div class="col-lg-3 col-sm-6"><div class="experiences-btn-wrp"><div class="experiences-btn"><?php if ( ! empty( $item['url'] ) ) : ?><a href="<?php echo esc_url( $item['url'] ); ?>"><i class="fa-solid fa-arrow-right"></i><?php echo esc_html( $item['experiences_name'] ?? '' ); ?></a><?php else : ?><span><?php echo esc_html( $item['experiences_name'] ?? '' ); ?></span><?php endif; ?></div></div></div><?php endforeach; ?></div></div></section>
<?php elseif ( 'advertising_with_image' === $type ) : ?>
	<section class="advertising-wrp bg_black padding_top_bottom"><div class="container"><?php $tabs = (array) ( $data['advertising_nav_section'] ?? array() ); if ( ! empty( $data['heading'] ) ) : ?><div class="heading text-center"><h2 class="text-white"><?php echo esc_html( $data['heading'] ); ?></h2></div><?php endif; ?><ul class="advertising-nav-new advertising-nav nav nav-pills" role="tablist"><?php foreach ( $tabs as $i => $tab ) : ?><li class="nav-item"><button class="nav-link<?php echo 0 === $i ? ' active' : ''; ?>" data-bs-toggle="pill" data-bs-target="#<?php echo esc_attr( $uid . '-' . $i ); ?>" type="button"><?php echo esc_html( $tab['advertising_nav_heading'] ?? '' ); ?></button></li><?php endforeach; ?></ul><div class="tab-content"><?php foreach ( $tabs as $i => $tab ) : ?><div class="tab-pane fade<?php echo 0 === $i ? ' show active' : ''; ?>" id="<?php echo esc_attr( $uid . '-' . $i ); ?>"><?php foreach ( (array) ( $tab['advertising_nav_details_section'] ?? array() ) as $item ) : ?><div class="row align-items-center justify-content-center"><div class="col-lg-5"><div class="heading"><h3><?php echo esc_html( $item['heading'] ?? '' ); ?></h3><div class="sub_pera grey-text"><?php echo wp_kses_post( wpautop( $item['advertising_nav_details'] ?? '' ) ); ?></div></div></div><div class="col-lg-5"><div class="ad-img"><?php echo $image( $item['image'] ?? null ); // phpcs:ignore ?></div></div></div><?php endforeach; ?></div><?php endforeach; ?></div></div></section>
<?php elseif ( 'support_growth' === $type ) : ?>
	<section class="support-wrp grey-bg padding_top_bottom"><div class="container"><div class="row"><div class="col-lg-8"><div class="support-text"><div class="heading"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><?php echo wp_kses_post( wpautop( $data['description'] ?? '' ) ); ?></div></div></div></div><div class="row justify-content-center"><?php foreach ( (array) ( $data['steps_to_growth'] ?? array() ) as $step_index => $step ) : ?><div class="col-lg-2 col-sm-4 col-6"><div class="support-icons-wrp"><div class="numeric_number"><p><?php echo esc_html( sprintf( '%02d', $step_index + 1 ) ); ?></p></div><div class="main-nav"><p class="bg_yellow"><?php echo esc_html( $step['growth_step_heading'] ?? '' ); ?></p></div><div class="sub_pera"><?php echo wp_kses_post( wpautop( $step['growth_step_short_description'] ?? '' ) ); ?></div></div></div><?php endforeach; ?></div></div></section>
	<?php get_template_part( 'template-parts/services-v2/sections/expertise' ); ?>
<?php elseif ( 'performance' === $type ) : ?>
	<section class="proformance-wrp padding_top_bottom"><div class="container"><div class="row align-items-center justify-content-center"><div class="col-lg-8"><div class="proformance-text text-center"><div class="heading"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><div class="sub_pera"><?php echo wp_kses_post( $data['description'] ?? '' ); ?></div></div></div><?php if ( ! empty( $data['button_url'] ) && ! empty( $data['button_text'] ) ) : ?><div class="main_btn"><a class="bg_yellow" href="<?php echo esc_url( $data['button_url'] ); ?>"><?php echo esc_html( $data['button_text'] ); ?><i class="fa-solid fa-arrow-right"></i></a></div><?php endif; ?></div></div></div></section>
<?php elseif ( 'service_brand' === $type ) : ?>
	<section class="self_brand service_brand padding_top_bottom"><div class="container"><div class="row"><?php foreach ( array(array('marketing_heading','icon','marketing_pera'),array('marketing_heading_second','icon_two','marketing_pera_two')) as $keys ) : ?><div class="col-lg-6 col-sm-6"><div class="introduction_wrp"><div class="introduction_heading"><h3><?php echo esc_html( $data[$keys[0]] ?? '' ); ?></h3></div><div class="brand_logo"><?php echo $image( $data[$keys[1]] ?? null, 'medium' ); // phpcs:ignore ?></div><div class="bottom_pera"><?php echo wp_kses_post( wpautop( $data[$keys[2]] ?? '' ) ); ?></div><div class="main_btn"><a class="bg_black" href="<?php echo esc_url( home_url( '/contact/' ) ); ?>"><?php esc_html_e( 'Contact Us Now!', 'di-infotech' ); ?><i class="fa-solid fa-arrow-right"></i></a></div></div></div><?php endforeach; ?></div></div></section>
<?php elseif ( 'faq' === $type ) : ?>
	<section class="faq-wrp padding_top_bottom"><div class="container"><div class="faq-text"><div class="heading"><h2><?php echo esc_html( $data['heading'] ?? '' ); ?></h2><?php echo wp_kses_post( wpautop( $data['description'] ?? '' ) ); ?></div></div><div class="row justify-content-center"><div class="col-lg-7"><div class="accordion" id="<?php echo esc_attr( $uid ); ?>"><?php foreach ( (array) ( $data['faqs'] ?? array() ) as $i => $faq ) : ?><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button<?php echo 0 === $i ? '' : ' collapsed'; ?>" type="button" data-bs-toggle="collapse" data-bs-target="#<?php echo esc_attr( $uid . '-' . $i ); ?>"><?php echo esc_html( $faq['faq_heading'] ?? '' ); ?></button></h3><div id="<?php echo esc_attr( $uid . '-' . $i ); ?>" class="accordion-collapse collapse<?php echo 0 === $i ? ' show' : ''; ?>" data-bs-parent="#<?php echo esc_attr( $uid ); ?>"><div class="accordion-body"><?php echo wp_kses_post( wpautop( $faq['faq_description'] ?? '' ) ); ?></div></div></div><?php endforeach; ?></div></div></div></div></section>
<?php endif; ?>
